1	'use client'
2	
3	import { useState, useCallback, useEffect, useMemo } from 'react'
4	import { useSearchParams, useRouter } from 'next/navigation'
5	import { Users, SearchX, BookmarkX, Plus, Loader2 } from 'lucide-react'
6	import { toast } from 'sonner'
7	import { Button } from '@/components/ui/button'
8	import { ClientsTable } from '@/components/clients/ClientsTable'
9	import { ClientFilterBar, type ClientFilters } from '@/components/clients/ClientFilterBar'
10	import { BulkActionsBar } from '@/components/clients/BulkActionsBar'
11	import { SavedViewSwitcher, type ClientView } from '@/components/clients/SavedViewSwitcher'
12	import { SavedViewManager } from '@/components/clients/SavedViewManager'
13	import { ClientDrawer } from '@/components/clients/ClientDrawer'
14	import dynamic from 'next/dynamic'
15	import { Skeleton } from '@/components/ui/skeleton'
16	
17	// B3 fix: code-split Tiptap out of the /clients route initial bundle (~130KB)
18	const AddNoteModal = dynamic(
19	  () => import('@/components/clients/notes/AddNoteModal').then((m) => ({ default: m.AddNoteModal })),
20	  { ssr: false, loading: () => <Skeleton className="h-10 w-full rounded-lg" /> },
21	)
22	import { DataState } from '@/components/shared/DataState'
23	import { EmptyState } from '@/components/shared/EmptyState'
24	import { PageError } from '@/components/shared/PageError'
25	import { PageViews } from '@/components/shared/PageViews'
26	import { PullToRefresh } from '@/components/shared/PullToRefresh'
27	import { TableSkeleton } from '@/components/skeletons'
28	import { Alert, AlertDescription } from '@/components/ui/alert'
29	import type { ClientTag } from '@/components/clients/TagChip'
30	import type { Database } from '@/lib/supabase/types'
31	
32	type Client = Database['public']['Tables']['clients']['Row']
33	
34	interface ClientsPageClientProps {
35	  initialClients: Client[]
36	  tagLibrary: ClientTag[]
37	}
38	
39	const DEFAULT_FILTERS: ClientFilters = {
40	  q: '',
41	  tags: [],
42	  vip: false,
43	  inactive: false,
44	  noShows: false,
45	  showArchived: false,
46	  hasAlerts: false,
47	  spendingTier: '',
48	  artistIds: [],
49	  serviceIds: [],
50	  lastVisitRange: '',
51	}
52	
53	export function ClientsPageClient({ initialClients, tagLibrary }: ClientsPageClientProps) {
54	  const router = useRouter()
55	  const searchParams = useSearchParams()
56	
57	  const [clients, setClients] = useState<Client[]>(initialClients)
58	  const [filters, setFilters] = useState<ClientFilters>(DEFAULT_FILTERS)
59	  const [selectedIds, setSelectedIds] = useState<string[]>([])
60	  const [loading, setLoading] = useState(false)
61	  const [fetchError, setFetchError] = useState<Error | null>(null)
62	  const [drawerOpen, setDrawerOpen] = useState(false)
63	  const [editingClient, setEditingClient] = useState<Client | null>(null)
64	  const [noteClientId, setNoteClientId] = useState<string | null>(null)
65	  const [page, setPage] = useState(1)
66	  const [hasMore, setHasMore] = useState(false)
67	  const [totalCount, setTotalCount] = useState<number | null>(null)
68	
69	  // Saved views
70	  const [views, setViews] = useState<ClientView[]>([])
71	  const [activeViewId, setActiveViewId] = useState<string | null>(null)
72	  const [viewManagerOpen, setViewManagerOpen] = useState(false)
73	  const [viewManagerMode, setViewManagerMode] = useState<'create' | 'edit'>('create')
74	  const [editingView, setEditingView] = useState<ClientView | null>(null)
75	  const [hasUnsavedChanges, setHasUnsavedChanges] = useState(false)
76	
77	  const fetchViews = useCallback(async () => {
78	    try {
79	      const res = await fetch('/api/client-views')
80	      if (res.ok) {
81	        const json = await res.json() as { data: ClientView[] }
82	        setViews(json.data ?? [])
83	        // Auto-activate first system default view
84	        const defaultView = json.data?.find((v) => v.is_default)
85	        if (defaultView) {
86	          setActiveViewId((prev) => prev ?? defaultView.id)
87	        }
88	      }
89	    } catch {
90	      toast.error('Failed to load views', { description: 'Using All clients as default' })
91	    }
92	  }, [])
93	
94	  // Load saved views on mount
95	  useEffect(() => {
96	    void fetchViews()
97	  }, [fetchViews])
98	
99	  // Restore page from URL
100	  useEffect(() => {
101	    const p = parseInt(searchParams.get('page') ?? '1', 10)
102	    if (p > 1) {
103	      setPage(p)
104	    }
105	  }, []) // eslint-disable-line react-hooks/exhaustive-deps
106	
107	  const fetchClients = useCallback(async (f: ClientFilters, p = 1) => {
108	    setLoading(true)
109	    setFetchError(null)
110	    try {
111	      const params = new URLSearchParams()
112	      if (f.q) params.set('q', f.q)
113	      if (f.tags.length) params.set('tags', f.tags.join(','))
114	      if (f.vip) params.set('vip', 'true')
115	      if (f.inactive) params.set('inactive', 'true')
116	      if (f.noShows) params.set('no_show', 'true')
117	      if (!f.showArchived) params.set('archived', 'false')
118	      else params.set('archived', 'any')
119	      if (f.spendingTier) params.set('spending', f.spendingTier)
120	      if (f.artistIds.length) params.set('artist_ids', f.artistIds.join(','))
121	      if (f.serviceIds.length) params.set('service_ids', f.serviceIds.join(','))
122	      if (f.lastVisitRange) params.set('last_visit_range', f.lastVisitRange)
123	      params.set('page', String(p))
124	      params.set('per_page', '50')
125	
126	      const res = await fetch(`/api/clients?${params.toString()}`)
127	      if (!res.ok) throw new Error('Failed to load clients')
128	      const json = await res.json() as { data: Client[]; count: number }
129	
130	      if (p === 1) {
131	        setClients(json.data ?? [])
132	      } else {
133	        setClients((prev) => [...prev, ...(json.data ?? [])])
134	      }
135	      setTotalCount(json.count ?? null)
136	      setHasMore((json.data?.length ?? 0) >= 50)
137	    } catch (err) {
138	      setFetchError(err instanceof Error ? err : new Error('Failed to load clients'))
139	    } finally {
140	      setLoading(false)
141	    }
142	  }, [])
143	
144	  useEffect(() => {
145	    void fetchClients(filters, 1)
146	    setPage(1)
147	    setSelectedIds([])
148	  }, [filters, fetchClients])
149	
150	  function handleFiltersChange(f: ClientFilters) {
151	    setFilters(f)
152	    setHasUnsavedChanges(true)
153	  }
154	
155	  function handleViewChange(viewId: string | null) {
156	    setActiveViewId(viewId)
157	    setHasUnsavedChanges(false)
158	    const view = views.find((v) => v.id === viewId)
159	    if (view) {
160	      // Apply view filters
161	      const viewFilters = view.filters as Partial<ClientFilters>
162	      setFilters({ ...DEFAULT_FILTERS, ...viewFilters })
163	    } else {
164	      setFilters(DEFAULT_FILTERS)
165	    }
166	  }
167	
168	  async function handleDeleteView(viewId: string) {
169	    try {
170	      const res = await fetch(`/api/client-views/${viewId}`, { method: 'DELETE' })
171	      if (!res.ok) throw new Error('Failed to delete view')
172	      setViews((prev) => prev.filter((v) => v.id !== viewId))
173	      if (activeViewId === viewId) {
174	        const defaultView = views.find((v) => v.is_default)
175	        setActiveViewId(defaultView?.id ?? null)
176	      }
177	      toast.success('View deleted')
178	    } catch {
179	      toast.error('Failed to delete view')
180	    }
181	  }
182	
183	  async function handleDuplicateView(view: ClientView) {
184	    try {
185	      const res = await fetch('/api/client-views', {
186	        method: 'POST',
187	        headers: { 'Content-Type': 'application/json' },
188	        body: JSON.stringify({
189	          name: `${view.name} (copy)`,
190	          filters: view.filters,
191	          scope: 'private',
192	        }),
193	      })
194	      if (!res.ok) throw new Error('Failed to duplicate view')
195	      const json = await res.json() as { data: ClientView }
196	      setViews((prev) => [...prev, json.data])
197	      toast.success('View duplicated')
198	    } catch {
199	      toast.error('Failed to duplicate view')
200	    }
201	  }
202	
203	  async function handleSetDefaultView(view: ClientView) {
204	    try {
205	      const res = await fetch(`/api/client-views/${view.id}`, {
206	        method: 'PATCH',
207	        headers: { 'Content-Type': 'application/json' },
208	        body: JSON.stringify({ is_default: true }),
209	      })
210	      if (!res.ok) throw new Error('Failed to set default')
211	      // Optimistically update local state so the star + dropdown sync instantly.
212	      setViews((prev) => prev.map((v) => ({ ...v, is_default: v.id === view.id })))
213	      toast.success(`"${view.name}" is now your default view`)
214	    } catch {
215	      toast.error('Failed to set default view')
216	    }
217	  }
218	
219	  function handleViewSaved(savedView: ClientView) {
220	    setViews((prev) => {
221	      const idx = prev.findIndex((v) => v.id === savedView.id)
222	      if (idx >= 0) {
223	        const next = [...prev]
224	        next[idx] = savedView
225	        return next
226	      }
227	      return [...prev, savedView]
228	    })
229	    setActiveViewId(savedView.id)
230	    setHasUnsavedChanges(false)
231	  }
232	
233	  function handleLoadMore() {
234	    const nextPage = page + 1
235	    setPage(nextPage)
236	    router.replace(`?page=${nextPage}`, { scroll: false })
237	    void fetchClients(filters, nextPage)
238	  }
239	
240	  function handleEditClient(client: Client) {
241	    setEditingClient(client)
242	    setDrawerOpen(true)
243	  }
244	
245	  function handleNewClient() {
246	    setEditingClient(null)
247	    setDrawerOpen(true)
248	  }
249	
250	  function handleDrawerSuccess(client: Client) {
251	    // Optimistic local patch — new row appears instantly even before the refetch
252	    // resolves. On edit we swap in place, on create we prepend.
253	    setClients((prev) => {
254	      const idx = prev.findIndex((c) => c.id === client.id)
255	      if (idx >= 0) {
256	        const next = [...prev]
257	        next[idx] = client
258	        return next
259	      }
260	      return [client, ...prev]
261	    })
262	    // Refetch so totalCount, server-side filter matching, and joined fields
263	    // (spending tier, last_visit, tags) reflect the authoritative server state.
264	    void fetchClients(filters, 1)
265	  }
266	
267	  const hasActiveFilters = !!(
268	    filters.q || filters.tags.length > 0 || filters.vip ||
269	    filters.inactive || filters.noShows || filters.spendingTier ||
270	    filters.artistIds.length > 0 || filters.serviceIds.length > 0 || filters.lastVisitRange
271	  )
272	
273	  const inactiveCount = useMemo(() => {
274	    const cutoff = Date.now() - 90 * 24 * 60 * 60 * 1000
275	    return clients.filter(
276	      (c) => !c.archived_at && c.last_visit_at !== null && new Date(c.last_visit_at).getTime() < cutoff
277	    ).length
278	  }, [clients])
279	
280	  const activeView = views.find((v) => v.id === activeViewId) ?? null
281	  const isInitialLoad = loading && clients.length === 0
282	
283	  return (
284	    <PullToRefresh
285	      onRefresh={async () => { router.refresh() }}
286	      className="flex flex-col gap-6"
287	    >
288	      {/* Views + actions row — saved-view pills on the left, count + primary
289	          action on the right. Bordered hairline spans the full row, matching
290	          the tab-row treatment used on /appointments, /inventory, etc.
291	          The page-level heading + description are rendered by the server
292	          page's PageHeader. */}
293	      <PageViews
294	        bordered
295	        actions={
296	          <>
297	            {totalCount !== null && (
298	              <span className="text-xs text-muted-foreground tabular-nums whitespace-nowrap">
299	                {clients.length} of {totalCount} client{totalCount !== 1 ? 's' : ''}
300	              </span>
301	            )}
302	            {inactiveCount > 0 && (
303	              <span
304	                title={`${inactiveCount} client${inactiveCount !== 1 ? 's' : ''} not seen in 90+ days`}
305	                className="inline-flex items-center gap-1 rounded-full bg-destructive/10 text-destructive text-[11px] font-medium px-2 py-0.5 select-none"
306	              >
307	                <span className="h-1.5 w-1.5 rounded-full bg-destructive shrink-0" aria-hidden="true" />
308	                {inactiveCount} inactive
309	              </span>
310	            )}
311	            <Button size="sm" onClick={handleNewClient}>
312	              <Plus className="mr-1.5 h-3.5 w-3.5" aria-hidden="true" />
313	              New client
314	            </Button>
315	          </>
316	        }
317	      >
318	        {views.length > 0 ? (
319	          <SavedViewSwitcher
320	            views={views}
321	            activeViewId={activeViewId}
322	            onViewChange={handleViewChange}
323	            onCreateView={() => {
324	              setViewManagerMode('create')
325	              setEditingView(null)
326	              setViewManagerOpen(true)
327	            }}
328	            onEditView={(view) => {
329	              setViewManagerMode('edit')
330	              setEditingView(view)
331	              setViewManagerOpen(true)
332	            }}
333	            onDuplicateView={handleDuplicateView}
334	            onDeleteView={handleDeleteView}
335	            onSetDefault={handleSetDefaultView}
336	          />
337	        ) : (
338	          <div className="h-10" aria-hidden="true" />
339	        )}
340	      </PageViews>
341	
342	      {/* Unsaved changes banner */}
343	      {hasUnsavedChanges && activeView && !activeView.is_system && (
344	        <Alert className="py-2 border-warning/30 bg-warning/5">
345	          <AlertDescription className="flex items-center justify-between gap-3 text-xs">
346	            <span className="text-warning dark:text-warning-foreground">
347	              Unsaved changes. Save view or discard?
348	            </span>
349	            <div className="flex gap-2 shrink-0">
350	              <Button
351	                size="sm"
352	                variant="outline"
353	                className="h-6 text-xs px-2"
354	                onClick={() => {
355	                  setFilters({ ...DEFAULT_FILTERS, ...(activeView.filters as Partial<ClientFilters>) })
356	                  setHasUnsavedChanges(false)
357	                }}
358	              >
359	                Discard
360	              </Button>
361	              <Button
362	                size="sm"
363	                className="h-6 text-xs px-2"
364	                onClick={() => {
365	                  setViewManagerMode('edit')
366	                  setEditingView(activeView)
367	                  setViewManagerOpen(true)
368	                }}
369	              >
370	                Save view
371	              </Button>
372	            </div>
373	          </AlertDescription>
374	        </Alert>
375	      )}
376	
377	      <ClientFilterBar
378	        filters={filters}
379	        onChange={handleFiltersChange}
380	        tagLibrary={tagLibrary}
381	      />
382	
383	      {selectedIds.length > 0 && (
384	        <BulkActionsBar
385	          selectedIds={selectedIds}
386	          tagLibrary={tagLibrary}
387	          onClearSelection={() => setSelectedIds([])}
388	          onArchived={() => void fetchClients(filters, 1)}
389	          onTagsApplied={() => void fetchClients(filters, 1)}
390	        />
391	      )}
392	
393	      <DataState
394	        data={clients}
395	        isLoading={isInitialLoad}
396	        isError={!!fetchError && clients.length === 0}
397	        error={fetchError}
398	        loadingSlot={<TableSkeleton rows={8} />}
399	        emptySlot={
400	          // Two distinct empty states per Clients Audit v1:
401	          //  1. DB empty (no clients ever created) — onboarding: + New client + CSV hint.
402	          //  2. Filters or saved view returned zero — help user reset.
403	          hasActiveFilters || (activeView && activeViewId) ? (
404	            activeView && activeViewId ? (
405	              <EmptyState
406	                icon={BookmarkX}
407	                title="No clients match these filters"
408	                description={`The filters in "${activeView.name}" returned no results.`}
409	                cta={{
410	                  label: 'Clear filters',
411	                  onClick: () => {
412	                    setFilters(DEFAULT_FILTERS)
413	                    setHasUnsavedChanges(false)
414	                  },
415	                }}
416	                ctaSecondary={{
417	                  label: 'Edit view filters',
418	                  onClick: () => {
419	                    setViewManagerMode('edit')
420	                    setEditingView(activeView)
421	                    setViewManagerOpen(true)
422	                  },
423	                }}
424	                variant="no-results"
425	              />
426	            ) : (
427	              <EmptyState
428	                icon={SearchX}
429	                title="No clients match these filters"
430	                description="Try different filters or clear all to see everyone."
431	                cta={{
432	                  label: 'Clear filters',
433	                  onClick: () => {
434	                    setFilters(DEFAULT_FILTERS)
435	                    setHasUnsavedChanges(false)
436	                  },
437	                }}
438	                variant="no-results"
439	              />
440	            )
441	          ) : (
442	            <EmptyState
443	              icon={Users}
444	              title="Add your first client"
445	              description="Start with a manual entry — CSV import is coming soon."
446	              cta={{ label: '+ New client', onClick: handleNewClient }}
447	              ctaSecondary={{
448	                label: 'Import from CSV',
449	                onClick: () => toast.info('CSV import is coming soon. Add clients manually for now.'),
450	              }}
451	              variant="first-time"
452	            />
453	          )
454	        }
455	        errorSlot={
456	          <PageError
457	            error={fetchError ?? new Error('Failed to load clients')}
458	            reset={() => void fetchClients(filters, 1)}
459	            variant="inline"
460	          />
461	        }
462	      >
463	        {(data) => (
464	          <ClientsTable
465	            clients={data}
466	            tagLibrary={tagLibrary}
467	            loading={loading && data.length === 0}
468	            selectedIds={selectedIds}
469	            onSelectionChange={setSelectedIds}
470	            onEdit={handleEditClient}
471	            onAddNote={(id) => setNoteClientId(id)}
472	          />
473	        )}
474	      </DataState>
475	
476	      {/* Load more */}
477	      {(hasMore || loading) && clients.length > 0 && (
478	        <div className="flex items-center justify-between py-4">
479	          <span className="text-sm text-muted-foreground tabular-nums">
480	            Showing {clients.length}{totalCount !== null ? ` of ${totalCount}` : ''} clients
481	          </span>
482	          {hasMore && (
483	            <Button variant="outline" size="sm" onClick={handleLoadMore} disabled={loading}>
484	              {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" aria-hidden="true" />}
485	              Load more
486	            </Button>
487	          )}
488	        </div>
489	      )}
490	
491	      <ClientDrawer
492	        open={drawerOpen}
493	        onOpenChange={(v) => {
494	          setDrawerOpen(v)
495	          if (!v) setEditingClient(null)
496	        }}
497	        client={editingClient}
498	        tagLibrary={tagLibrary}
499	        onSuccess={handleDrawerSuccess}
500	      />
501	
502	      {noteClientId && (
503	        <AddNoteModal
504	          open={Boolean(noteClientId)}
505	          onOpenChange={(v) => { if (!v) setNoteClientId(null) }}
506	          clientId={noteClientId}
507	        />
508	      )}
509	
510	      <SavedViewManager
511	        open={viewManagerOpen}
512	        onOpenChange={setViewManagerOpen}
513	        mode={viewManagerMode}
514	        view={editingView}
515	        currentFilters={filters}
516	        onSaved={handleViewSaved}
517	      />
518	    </PullToRefresh>
519	  )
520	}
521

1	@import "tailwindcss";
2	@import "tw-animate-css";
3	@import "shadcn/tailwind.css";
4	
5	@custom-variant dark (&:is(.dark *));
6	
7	@theme inline {
8	  /* ──────────────────────────────────────────────────────────
9	     INKOS BRAND SWATCHES — Brand Book v1.0 (LOCKED)
10	     Bone · Onyx · Stone · Rust — no additions, no substitutes
11	  ────────────────────────────────────────────────────────── */
12	  --color-bone: #F7F7F5;
13	  --color-onyx: #0F0F0F;
14	  --color-stone: #787774;
15	  --color-rust: #B23A2B;
16	
17	  --font-sans: var(--font-sans), 'Inter', -apple-system, sans-serif;
18	  --font-serif: var(--font-serif), 'Instrument Serif', Georgia, serif;
19	  --font-mono: var(--font-mono), 'JetBrains Mono', monospace;
20	
21	  /* ──────────────────────────────────────────────────────────
22	     SEMANTIC PALETTE — derived from brand swatches
23	     Rule: never pure #FFF or #000. Bone/Onyx only.
24	  ────────────────────────────────────────────────────────── */
25	
26	  /* Bone — 60% usage. Page canvas + sidebar bg. */
27	  --color-background: #F7F7F5;
28	
29	  /* Onyx — 20% usage. Primary text + CTAs. */
30	  --color-foreground: #0F0F0F;
31	
32	  /* Card surface — pure white on Bone, so cards "float" */
33	  --color-card: #FFFFFF;
34	  --color-card-foreground: #0F0F0F;
35	
36	  --color-popover: #FFFFFF;
37	  --color-popover-foreground: #0F0F0F;
38	
39	  /* Primary = Onyx (NOT Rust). Primary CTAs are black. */
40	  --color-primary: #0F0F0F;
41	  --color-primary-foreground: #F7F7F5;
42	
43	  /* Secondary — muted Bone tint */
44	  --color-secondary: oklch(96% 0.003 60);
45	  --color-secondary-foreground: #0F0F0F;
46	
47	  /* Muted — Stone-tinted backgrounds */
48	  --color-muted: oklch(95% 0.003 60);
49	  --color-muted-foreground: #787774;
50	
51	  /* Accent — Rust at 12% opacity for active nav states */
52	  --color-accent: rgba(178, 58, 43, 0.08);
53	  --color-accent-foreground: #B23A2B;
54	
55	  /* Destructive = Rust. Reserved for LIVE pill, active nav, destructive only. */
56	  --color-destructive: #B23A2B;
57	  --color-destructive-foreground: #F7F7F5;
58	
59	  /* ──────────────────────────────────────────────────────────
60	     SEMANTIC STATUS TOKENS
61	  ────────────────────────────────────────────────────────── */
62	  --color-success:            oklch(58% 0.18 145);
63	  --color-success-bg:         oklch(94% 0.05 145);
64	  --color-success-foreground: oklch(26% 0.12 145);
65	  --color-warning:            oklch(70% 0.16 72);
66	  --color-warning-bg:         oklch(94% 0.07 72);
67	  --color-warning-foreground: oklch(36% 0.15 72);
68	
69	  /* Borders — Stone-tinted, warm hue, tuned to be visible on bone canvas */
70	  --color-border: oklch(91% 0.005 85);
71	  --color-input: oklch(91% 0.005 85);
72	  --color-ring: #0F0F0F;
73	
74	  /* ──────────────────────────────────────────────────────────
75	     SHADOWS — custom (never use Tailwind default shadow-sm/md)
76	  ────────────────────────────────────────────────────────── */
77	
78	  /* Soft border shadow for cards on white — bumped alpha so cards read on bone bg */
79	  --shadow-soft: 0 1px 2px 0 oklch(20% 0.02 85 / 0.08), 0 1px 3px 0 oklch(20% 0.02 85 / 0.05);
80	
