'use client'

import { useRef } from 'react'
import { Plus, Star, MoreHorizontal } from 'lucide-react'
import { Button } from '@/components/ui/button'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import { cn } from '@/lib/utils'
import type { ClientView } from '@/components/clients/SavedViewSwitcher'

interface ClientsViewTabsProps {
  views: ClientView[]
  activeViewId: string | null
  /** When true, renders a • dot indicator on the active tab label */
  hasUnsavedChanges?: boolean
  onViewChange: (viewId: string | null) => void
  onCreateView: () => void
  onEditView: (view: ClientView) => void
  onDuplicateView: (view: ClientView) => void
  onDeleteView: (viewId: string) => void
  onSetDefault: (view: ClientView) => void
}

export function ClientsViewTabs({
  views,
  activeViewId,
  hasUnsavedChanges = false,
  onViewChange,
  onCreateView,
  onEditView,
  onDuplicateView,
  onDeleteView,
  onSetDefault,
}: ClientsViewTabsProps) {
  const listRef = useRef<HTMLDivElement>(null)

  function handleKeyDown(
    e: React.KeyboardEvent<HTMLButtonElement>,
    currentIndex: number
  ) {
    const triggers = listRef.current?.querySelectorAll<HTMLButtonElement>(
      '[role="tab"]'
    )
    if (!triggers) return
    let nextIndex: number | null = null
    if (e.key === 'ArrowRight') {
      nextIndex = (currentIndex + 1) % triggers.length
    } else if (e.key === 'ArrowLeft') {
      nextIndex = (currentIndex - 1 + triggers.length) % triggers.length
    } else if (e.key === 'Home') {
      nextIndex = 0
    } else if (e.key === 'End') {
      nextIndex = triggers.length - 1
    }
    if (nextIndex !== null) {
      e.preventDefault()
      triggers[nextIndex]?.focus()
    }
  }

  return (
    <div
      ref={listRef}
      role="tablist"
      aria-label="Client views"
      className={cn(
        'flex items-end gap-0',
        'overflow-x-auto scrollbar-none',
        // Fade edges on mobile
        '[mask-image:linear-gradient(to_right,transparent_0px,black_16px,black_calc(100%-16px),transparent_100%)]',
        'md:[mask-image:none]',
      )}
    >
      {views.map((view, index) => {
        const isActive = view.id === activeViewId

        const tabButton = (
          <button
            type="button"
            role="tab"
            aria-selected={isActive}
            onClick={() => !isActive && onViewChange(view.id)}
            onKeyDown={(e) => handleKeyDown(e, index)}
            className={cn(
              'group/tab relative flex items-center gap-1.5 px-3 h-10 shrink-0',
              'text-sm whitespace-nowrap transition-colors duration-150',
              'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-0',
              isActive
                ? [
                    'font-semibold text-foreground',
                    // Rust underline — 2px, flush to bottom
                    'after:absolute after:bottom-0 after:inset-x-0 after:h-0.5 after:bg-rust after:rounded-full',
                  ]
                : 'font-medium text-muted-foreground hover:text-foreground',
            )}
          >
            {view.is_default && (
              <Star
                className="h-3 w-3 shrink-0 fill-rust text-rust"
                aria-label="Default view"
              />
            )}
            <span>{view.name}</span>
            {/* Unsaved-changes dot — only on active tab */}
            {isActive && hasUnsavedChanges && !view.is_system && (
              <span
                className="ml-0.5 h-1.5 w-1.5 rounded-full bg-rust shrink-0"
                aria-label="Unsaved changes"
              />
            )}
            {/* Kebab: always visible on active tab, hover-visible on inactive */}
            <span
              className={cn(
                'ml-0.5 flex items-center',
                isActive
                  ? 'opacity-100'
                  : 'opacity-0 group-hover/tab:opacity-100 focus-within:opacity-100'
              )}
            >
              <MoreHorizontal className="h-3.5 w-3.5 text-muted-foreground" aria-hidden="true" />
            </span>
          </button>
        )

        return (
          <div key={view.id} className="flex shrink-0">
            <DropdownMenu>
              {/* DropdownMenuTrigger wrapping the whole tab button to capture the
                  kebab click. We use render= to pass the styled tab button directly. */}
              <DropdownMenuTrigger
                render={tabButton}
                onClick={(e) => {
                  // Only open the dropdown when the MoreHorizontal icon was clicked
                  // (last child of the button). If user clicks the tab label/name,
                  // we propagate normally so the tab selects. The DropdownMenuTrigger
                  // with render= captures the whole button; we stop propagation on the
                  // icon-area click by checking target proximity in the tab button's
                  // own onClick instead.
                  // Actually: since the whole button is the trigger, we suppress
                  // the view-change call inside the button's onClick when the
                  // dropdown is about to open. The simplest pattern: always let
                  // the dropdown open on ANY click, then call onViewChange inside
                  // the DropdownMenu onOpenChange callback when it CLOSES if nothing
                  // was clicked. That's complex. Instead, split into two elements:
                  // a click-zone for the label and a separate trigger for the kebab.
                  void e
                }}
              />
              <DropdownMenuContent align="start">
                {view.is_default ? (
                  <DropdownMenuItem disabled className="gap-2 text-xs text-muted-foreground">
                    <Star className="h-3.5 w-3.5 fill-rust text-rust" aria-hidden="true" />
                    Current default view
                  </DropdownMenuItem>
                ) : (
                  <DropdownMenuItem
                    onClick={() => onSetDefault(view)}
                    className="gap-2 text-xs"
                  >
                    <Star className="h-3.5 w-3.5" aria-hidden="true" />
                    Make this my default view
                  </DropdownMenuItem>
                )}
                {!view.is_system && (
                  <>
                    <DropdownMenuSeparator />
                    <DropdownMenuItem
                      className="text-xs"
                      onClick={() => onEditView(view)}
                    >
                      Edit view filters
                    </DropdownMenuItem>
                    <DropdownMenuItem
                      className="text-xs"
                      onClick={() => onDuplicateView(view)}
                    >
                      Duplicate view
                    </DropdownMenuItem>
                    <DropdownMenuSeparator />
                    <DropdownMenuItem
                      className="text-xs text-destructive focus:text-destructive"
                      onClick={() => onDeleteView(view.id)}
                    >
                      Delete view
                    </DropdownMenuItem>
                  </>
                )}
              </DropdownMenuContent>
            </DropdownMenu>
          </div>
        )
      })}

      {/* New view icon button */}
      <Button
        type="button"
        variant="ghost"
        size="icon"
        className="h-10 w-8 shrink-0 text-muted-foreground hover:text-foreground"
        onClick={onCreateView}
        aria-label="Create new view"
      >
        <Plus className="h-3.5 w-3.5" aria-hidden="true" />
      </Button>
    </div>
  )
}

