'use client'

import { Columns3 } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Checkbox } from '@/components/ui/checkbox'
import { Label } from '@/components/ui/label'
import { Separator } from '@/components/ui/separator'
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@/components/ui/popover'

export interface ColumnDef {
  key: string
  label: string
  alwaysVisible?: boolean
}

interface ColumnsPickerProps {
  columns: ColumnDef[]
  visibleKeys: string[]
  onChange: (keys: string[]) => void
}

export function ColumnsPicker({ columns, visibleKeys, onChange }: ColumnsPickerProps) {
  function handleToggle(key: string, checked: boolean) {
    if (checked) {
      onChange([...visibleKeys, key])
    } else {
      onChange(visibleKeys.filter((k) => k !== key))
    }
  }

  function handleReset() {
    onChange(columns.map((c) => c.key))
  }

  return (
    <Popover>
      <PopoverTrigger
        render={
          <Button variant="outline" size="sm" className="h-9 gap-1.5" aria-label="Configure columns">
            <Columns3 className="h-3.5 w-3.5" aria-hidden="true" />
            <span className="hidden md:inline">Columns</span>
          </Button>
        }
      />
      <PopoverContent align="end" className="w-56 p-3">
        <p className="text-[10px] font-semibold uppercase tracking-wide text-muted-foreground mb-2">
          Show columns
        </p>
        <div className="space-y-1.5">
          {columns.map((col) => {
            const isChecked = visibleKeys.includes(col.key)
            const id = `col-toggle-${col.key}`
            return (
              <div key={col.key} className="flex items-center gap-2 py-0.5">
                <Checkbox
                  id={id}
                  checked={col.alwaysVisible ? true : isChecked}
                  disabled={col.alwaysVisible}
                  onCheckedChange={(checked) => handleToggle(col.key, Boolean(checked))}
                  aria-label={`${col.alwaysVisible ? 'Always show' : isChecked ? 'Hide' : 'Show'} ${col.label} column`}
                />
                <Label htmlFor={id} className="text-sm font-normal cursor-pointer">
                  {col.label}
                </Label>
              </div>
            )
          })}
        </div>
        <Separator className="my-2" />
        <Button
          variant="ghost"
          size="sm"
          className="w-full h-7 text-xs"
          onClick={handleReset}
        >
          Reset to default
        </Button>
      </PopoverContent>
    </Popover>
  )
}

'use client'

import { useState } from 'react'
import { SlidersHorizontal, X } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Badge } from '@/components/ui/badge'
import { Separator } from '@/components/ui/separator'
import { Switch } from '@/components/ui/switch'
import { Label } from '@/components/ui/label'
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@/components/ui/popover'
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from '@/components/ui/command'
import { Checkbox } from '@/components/ui/checkbox'
import { cn } from '@/lib/utils'
import type { ClientTag } from '@/components/clients/TagChip'
import {
  SPENDING_OPTIONS,
  LAST_VISIT_OPTIONS,
  DEFAULT_FILTERS,
  type ClientFilters,
  type FilterArtist,
  type FilterService,
} from '@/components/clients/filters-types'

interface FiltersPopoverProps {
  filters: ClientFilters
  onApply: (filters: ClientFilters) => void
  tagLibrary: ClientTag[]
  artists?: FilterArtist[]
  services?: FilterService[]
  appliedCount: number
}

export function FiltersPopover({
  filters,
  onApply,
  tagLibrary,
  artists = [],
  services = [],
  appliedCount,
}: FiltersPopoverProps) {
  const [open, setOpen] = useState(false)
  // Draft state — only committed on Apply
  const [draft, setDraft] = useState<ClientFilters>(filters)

  function handleOpenChange(next: boolean) {
    if (next) {
      // Re-initialize draft from latest committed filters on open
      setDraft(filters)
    }
    setOpen(next)
  }

  function set<K extends keyof ClientFilters>(key: K, value: ClientFilters[K]) {
    setDraft((prev) => ({ ...prev, [key]: value }))
  }

  function toggleTag(id: string) {
    setDraft((prev) => ({
      ...prev,
      tags: prev.tags.includes(id)
        ? prev.tags.filter((t) => t !== id)
        : [...prev.tags, id],
    }))
  }

  function toggleArtist(id: string) {
    setDraft((prev) => ({
      ...prev,
      artistIds: prev.artistIds.includes(id)
        ? prev.artistIds.filter((a) => a !== id)
        : [...prev.artistIds, id],
    }))
  }

  function toggleService(id: string) {
    setDraft((prev) => ({
      ...prev,
      serviceIds: prev.serviceIds.includes(id)
        ? prev.serviceIds.filter((s) => s !== id)
        : [...prev.serviceIds, id],
    }))
  }

  function handleClear() {
    setDraft({ ...DEFAULT_FILTERS, q: filters.q, showArchived: filters.showArchived })
  }

  function handleApply() {
    onApply(draft)
    setOpen(false)
  }

  return (
    <Popover open={open} onOpenChange={handleOpenChange}>
      <PopoverTrigger
        render={
          <Button
            variant="outline"
            size="sm"
            className={cn(
              'h-9 gap-1.5',
              appliedCount > 0 && 'border-rust/30 bg-rust/5 text-foreground',
            )}
            aria-label={appliedCount > 0 ? `Filters (${appliedCount} active)` : 'Filters'}
          >
            <SlidersHorizontal className="h-3.5 w-3.5" aria-hidden="true" />
            Filters
            {appliedCount > 0 && (
              <Badge className="ml-0.5 h-4 min-w-[18px] px-1 text-[10px] font-semibold bg-rust text-bone">
                {appliedCount}
              </Badge>
            )}
          </Button>
        }
      />
      <PopoverContent
        align="start"
        className="w-[360px] sm:w-[400px] p-0"
        onInteractOutside={() => setOpen(false)}
        onEscapeKeyDown={() => setOpen(false)}
      >
        <div className="p-4 space-y-4 max-h-[80vh] overflow-y-auto">
          {/* Tags */}
          <section>
            <p className="text-[10px] font-semibold uppercase tracking-wide text-muted-foreground mb-2">
              Tags
            </p>
            {tagLibrary.length === 0 ? (
              <p className="text-xs text-muted-foreground">No tags created yet.</p>
            ) : (
              <Command className="border border-border/40 rounded-md">
                <CommandInput placeholder="Search tags…" className="h-8 text-sm" />
                <CommandList className="max-h-36">
                  <CommandEmpty>No tags match</CommandEmpty>
                  <CommandGroup>
                    {tagLibrary.map((tag) => (
                      <CommandItem
                        key={tag.id}
                        onSelect={() => toggleTag(tag.id)}
                        className="flex items-center gap-2 text-sm"
                      >
                        <Checkbox
                          checked={draft.tags.includes(tag.id)}
                          className="pointer-events-none"
                          aria-hidden
                        />
                        <span className={cn('h-2 w-2 rounded-full shrink-0', `tag-chip-${tag.color}`)} />
                        <span className="flex-1">{tag.name}</span>
                      </CommandItem>
                    ))}
                  </CommandGroup>
                </CommandList>
              </Command>
            )}
          </section>

          <Separator />

          {/* Spending tier */}
          <section>
            <p className="text-[10px] font-semibold uppercase tracking-wide text-muted-foreground mb-2">
              Spending tier
            </p>
            <div className="space-y-1">
              {SPENDING_OPTIONS.map((opt) => (
                <button
                  key={opt.value || '__any'}
                  type="button"
                  className={cn(
                    'w-full text-left text-sm px-2.5 py-1.5 rounded-md hover:bg-muted transition-colors',
                    draft.spendingTier === opt.value && 'bg-rust/10 text-foreground font-medium',
                  )}
                  onClick={() => set('spendingTier', opt.value)}
                >
                  {opt.label}
                </button>
              ))}
            </div>
          </section>

          <Separator />

          {/* Last visit */}
          <section>
            <p className="text-[10px] font-semibold uppercase tracking-wide text-muted-foreground mb-2">
              Last visit
            </p>
            <div className="space-y-1">
              {LAST_VISIT_OPTIONS.map((opt) => (
                <button
                  key={opt.value || '__any'}
                  type="button"
                  className={cn(
                    'w-full text-left text-sm px-2.5 py-1.5 rounded-md hover:bg-muted transition-colors',
                    draft.lastVisitRange === opt.value && 'bg-rust/10 text-foreground font-medium',
                  )}
                  onClick={() => set('lastVisitRange', opt.value)}
                >
                  {opt.label}
                </button>
              ))}
            </div>
          </section>

          <Separator />

          {/* Switches */}
          <section className="space-y-3">
            <p className="text-[10px] font-semibold uppercase tracking-wide text-muted-foreground">
              Client status
            </p>
            <div className="flex items-center justify-between gap-3">
              <Label htmlFor="filter-has-alerts" className="text-sm font-normal cursor-pointer">
                Has alerts
              </Label>
              <Switch
                id="filter-has-alerts"
                checked={draft.hasAlerts}
                onCheckedChange={(v) => set('hasAlerts', v)}
              />
            </div>
            <div className="flex items-center justify-between gap-3">
              <Label htmlFor="filter-no-shows" className="text-sm font-normal cursor-pointer">
                No-shows
              </Label>
              <Switch
                id="filter-no-shows"
                checked={draft.noShows}
                onCheckedChange={(v) => set('noShows', v)}
              />
            </div>
          </section>

          {/* Artist (conditional) */}
          {artists.length > 0 && (
            <>
              <Separator />
              <section>
                <p className="text-[10px] font-semibold uppercase tracking-wide text-muted-foreground mb-2">
                  Artist
                </p>
                <Command className="border border-border/40 rounded-md">
                  <CommandInput placeholder="Search artists…" className="h-8 text-sm" />
                  <CommandList className="max-h-36">
                    <CommandEmpty>No artists found</CommandEmpty>
                    <CommandGroup>
                      {artists.map((artist) => (
                        <CommandItem
                          key={artist.id}
                          onSelect={() => toggleArtist(artist.id)}
                          className="flex items-center gap-2 text-sm"
                        >
                          <Checkbox
                            checked={draft.artistIds.includes(artist.id)}
                            className="pointer-events-none"
                            aria-hidden
                          />
                          <span className="flex-1">{artist.display_name}</span>
                        </CommandItem>
                      ))}
                    </CommandGroup>
                  </CommandList>
                </Command>
              </section>
            </>
          )}

          {/* Service (conditional) */}
          {services.length > 0 && (
            <>
              <Separator />
              <section>
                <p className="text-[10px] font-semibold uppercase tracking-wide text-muted-foreground mb-2">
                  Service
                </p>
                <Command className="border border-border/40 rounded-md">
                  <CommandInput placeholder="Search services…" className="h-8 text-sm" />
                  <CommandList className="max-h-36">
                    <CommandEmpty>No services found</CommandEmpty>
                    <CommandGroup>
                      {services.map((service) => (
                        <CommandItem
                          key={service.id}
                          onSelect={() => toggleService(service.id)}
                          className="flex items-center gap-2 text-sm"
                        >
                          <Checkbox
                            checked={draft.serviceIds.includes(service.id)}
                            className="pointer-events-none"
                            aria-hidden
                          />
                          <span className="flex-1">{service.name}</span>
                        </CommandItem>
                      ))}
                    </CommandGroup>
                  </CommandList>
                </Command>
              </section>
            </>
          )}
        </div>

        {/* Footer */}
        <div className="flex items-center justify-between gap-2 border-t border-border/60 px-4 py-3">
          <Button
            variant="ghost"
            size="sm"
            className="h-8 text-xs gap-1"
            onClick={handleClear}
          >
            <X className="h-3 w-3" aria-hidden="true" />
            Clear
          </Button>
          <Button size="sm" className="h-8 text-xs" onClick={handleApply}>
            Apply
          </Button>
        </div>
      </PopoverContent>
    </Popover>
  )
}

'use client'

import { useRef } from 'react'
import { Search, X, Archive, Eye, MoreHorizontal } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Badge } from '@/components/ui/badge'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import { FiltersPopover } from '@/components/clients/FiltersPopover'
import { SortDropdown, type SortKey } from '@/components/clients/SortDropdown'
import { ColumnsPicker, type ColumnDef } from '@/components/clients/ColumnsPicker'
import type { ClientTag } from '@/components/clients/TagChip'
import {
  SPENDING_OPTIONS,
  LAST_VISIT_OPTIONS,
  DEFAULT_FILTERS,
  type ClientFilters,
  type FilterArtist,
  type FilterService,
} from '@/components/clients/filters-types'

export interface ClientsToolbarProps {
  search: string
  onSearchChange: (value: string) => void
  filters: ClientFilters
  onFiltersChange: (filters: ClientFilters) => void
  sort: SortKey
  onSortChange: (sort: SortKey) => void
  columns: ColumnDef[]
  visibleColumnKeys: string[]
  onVisibleColumnsChange: (keys: string[]) => void
  tagLibrary: ClientTag[]
  artists?: FilterArtist[]
  services?: FilterService[]
  showArchived: boolean
  onToggleArchived: () => void
}

export function ClientsToolbar({
  search,
  onSearchChange,
  filters,
  onFiltersChange,
  sort,
  onSortChange,
  columns,
  visibleColumnKeys,
  onVisibleColumnsChange,
  tagLibrary,
  artists = [],
  services = [],
  showArchived,
  onToggleArchived,
}: ClientsToolbarProps) {
  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  const searchRef = useRef<HTMLInputElement>(null)

  function handleSearchChange(e: React.ChangeEvent<HTMLInputElement>) {
    const val = e.target.value
    if (debounceRef.current) clearTimeout(debounceRef.current)
    debounceRef.current = setTimeout(() => {
      onSearchChange(val)
    }, 150)
  }

  // ── Applied filter count (excludes q and showArchived — those have their own UI) ──
  let appliedCount = 0
  if (filters.tags.length > 0) appliedCount++
  if (filters.spendingTier) appliedCount++
  if (filters.lastVisitRange) appliedCount++
  if (filters.hasAlerts) appliedCount++
  if (filters.noShows) appliedCount++
  if (filters.artistIds.length > 0) appliedCount++
  if (filters.serviceIds.length > 0) appliedCount++

  // ── Applied chip list ──
  interface Chip { key: string; label: string; onRemove: () => void }
  const activeChips: Chip[] = []

  if (filters.tags.length > 0) {
    for (const id of filters.tags) {
      const tag = tagLibrary.find((t) => t.id === id || t.name === id)
      activeChips.push({
        key: `tag-${id}`,
        label: tag?.name ?? id,
        onRemove: () =>
          onFiltersChange({ ...filters, tags: filters.tags.filter((t) => t !== id) }),
      })
    }
  }

  if (filters.spendingTier) {
    const label =
      SPENDING_OPTIONS.find((o) => o.value === filters.spendingTier)?.label ??
      filters.spendingTier
    activeChips.push({
      key: 'spending',
      label: `Spending: ${label}`,
      onRemove: () => onFiltersChange({ ...filters, spendingTier: '' }),
    })
  }

  if (filters.lastVisitRange) {
    const label =
      LAST_VISIT_OPTIONS.find((o) => o.value === filters.lastVisitRange)?.label ??
      filters.lastVisitRange
    activeChips.push({
      key: 'lastVisit',
      label: `Visit: ${label}`,
      onRemove: () => onFiltersChange({ ...filters, lastVisitRange: '' }),
    })
  }

  if (filters.hasAlerts) {
    activeChips.push({
      key: 'hasAlerts',
      label: 'Has alerts',
      onRemove: () => onFiltersChange({ ...filters, hasAlerts: false }),
    })
  }

  if (filters.noShows) {
    activeChips.push({
      key: 'noShows',
      label: 'No-shows',
      onRemove: () => onFiltersChange({ ...filters, noShows: false }),
    })
  }

  for (const id of filters.artistIds) {
    const artist = artists.find((a) => a.id === id)
    activeChips.push({
      key: `artist-${id}`,
      label: `Artist: ${artist?.display_name ?? id}`,
      onRemove: () =>
        onFiltersChange({ ...filters, artistIds: filters.artistIds.filter((a) => a !== id) }),
    })
  }

  for (const id of filters.serviceIds) {
    const service = services.find((s) => s.id === id)
    activeChips.push({
      key: `service-${id}`,
      label: `Service: ${service?.name ?? id}`,
      onRemove: () =>
        onFiltersChange({ ...filters, serviceIds: filters.serviceIds.filter((s) => s !== id) }),
    })
  }

  function clearAll() {
    onFiltersChange({ ...DEFAULT_FILTERS, q: filters.q, showArchived: filters.showArchived })
    if (searchRef.current) searchRef.current.value = filters.q
  }

  return (
    <div className="flex flex-col gap-3">
      {/* Toolbar row */}
      <div className="flex flex-wrap items-center gap-2">
        {/* Search — flex-1 */}
        <div className="relative flex-1 min-w-[200px] max-w-md">
          <Search
            className="absolute left-3 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-muted-foreground pointer-events-none"
            aria-hidden="true"
          />
          <Input
            ref={searchRef}
            defaultValue={search}
            onChange={handleSearchChange}
            placeholder="Search clients…"
            className="h-9 pl-9 text-sm"
            aria-label="Search clients"
          />
        </div>

        <FiltersPopover
          filters={filters}
          onApply={onFiltersChange}
          tagLibrary={tagLibrary}
          artists={artists}
          services={services}
          appliedCount={appliedCount}
        />

        {/* Spacer — pushes sort/columns to the right */}
        <div className="hidden sm:block sm:flex-1" />

        <SortDropdown value={sort} onChange={onSortChange} />
        <ColumnsPicker
          columns={columns}
          visibleKeys={visibleColumnKeys}
          onChange={onVisibleColumnsChange}
        />

        {/* Overflow menu (show/hide archived) */}
        <DropdownMenu>
          <DropdownMenuTrigger
            render={
              <Button
                variant="ghost"
                size="icon"
                className="h-9 w-9"
                aria-label="More options"
              >
                <MoreHorizontal className="h-4 w-4" aria-hidden="true" />
              </Button>
            }
          />
          <DropdownMenuContent align="end">
            <DropdownMenuItem
              onClick={onToggleArchived}
              className="gap-2 text-xs"
            >
              {showArchived ? (
                <Eye className="h-3.5 w-3.5" aria-hidden="true" />
              ) : (
                <Archive className="h-3.5 w-3.5" aria-hidden="true" />
              )}
              {showArchived ? 'Hide archived clients' : 'Show archived clients'}
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>
      </div>

      {/* Applied filter chips — only when active */}
      {activeChips.length > 0 && (
        <div className="flex flex-wrap items-center gap-1.5" role="list" aria-label="Active filters">
          {activeChips.map((chip) => (
            <Badge
              key={chip.key}
              variant="secondary"
              className="h-6 gap-1 pl-2.5 pr-1 text-xs cursor-default"
              role="listitem"
            >
              {chip.label}
              <button
                type="button"
                onClick={chip.onRemove}
                className="flex items-center justify-center rounded-sm hover:bg-muted-foreground/20 transition-colors"
                aria-label={`Remove ${chip.label} filter`}
              >
                <X className="h-3 w-3" aria-hidden="true" />
              </button>
            </Badge>
          ))}
          <button
            type="button"
            onClick={clearAll}
            className="text-xs text-muted-foreground hover:text-foreground underline underline-offset-2 transition-colors"
          >
            Clear all
          </button>
        </div>
      )}
    </div>
  )
}

'use client'

import { useState, useCallback, useEffect, useMemo } from 'react'
import { useSearchParams, useRouter } from 'next/navigation'
import { Users, SearchX, BookmarkX, Plus, Loader2 } from 'lucide-react'
import { toast } from 'sonner'
import { Button } from '@/components/ui/button'
import { ClientsTable } from '@/components/clients/ClientsTable'
import { ClientsToolbar } from '@/components/clients/ClientsToolbar'
import { ClientsViewTabs } from '@/components/clients/ClientsViewTabs'
import { BulkActionsBar } from '@/components/clients/BulkActionsBar'
import { SavedViewSwitcher, type ClientView } from '@/components/clients/SavedViewSwitcher'
import { SavedViewManager } from '@/components/clients/SavedViewManager'
import { ClientDrawer } from '@/components/clients/ClientDrawer'
import dynamic from 'next/dynamic'
import { Skeleton } from '@/components/ui/skeleton'

// B3 fix: code-split Tiptap out of the /clients route initial bundle (~130KB)
const AddNoteModal = dynamic(
  () => import('@/components/clients/notes/AddNoteModal').then((m) => ({ default: m.AddNoteModal })),
  { ssr: false, loading: () => <Skeleton className="h-10 w-full rounded-lg" /> },
)
import { DataState } from '@/components/shared/DataState'
import { EmptyState } from '@/components/shared/EmptyState'
import { PageError } from '@/components/shared/PageError'
import { PullToRefresh } from '@/components/shared/PullToRefresh'
import { TableSkeleton } from '@/components/skeletons'
import type { ClientTag } from '@/components/clients/TagChip'
import type { Database } from '@/lib/supabase/types'
import type { ColumnDef } from '@/components/clients/ColumnsPicker'
import type { SortKey } from '@/components/clients/SortDropdown'
import {
  DEFAULT_FILTERS,
  type ClientFilters,
} from '@/components/clients/filters-types'

type Client = Database['public']['Tables']['clients']['Row']

// ── Column definitions ──────────────────────────────────────────────────────
const COLUMN_DEFS: ColumnDef[] = [
  { key: 'client',     label: 'Client',    alwaysVisible: true },
  { key: 'tags',       label: 'Tags' },
  { key: 'last_visit', label: 'Last visit' },
  { key: 'spent',      label: 'Spent' },
  { key: 'sessions',   label: 'Sessions' },
  { key: 'source',     label: 'Source' },
  { key: 'contact',    label: 'Contact' },
]

const COLUMN_STORAGE_KEY = 'clients.columns.v1'

function getInitialVisibleKeys(): string[] {
  if (typeof window === 'undefined') return COLUMN_DEFS.map((c) => c.key)
  try {
    const stored = window.localStorage.getItem(COLUMN_STORAGE_KEY)
    if (stored) {
      const parsed = JSON.parse(stored) as unknown
      if (Array.isArray(parsed) && parsed.every((k) => typeof k === 'string')) {
        return parsed as string[]
      }
    }
  } catch {
    // Ignore — fall back to defaults
  }
  return COLUMN_DEFS.map((c) => c.key)
}

// ────────────────────────────────────────────────────────────────────────────

interface ClientsPageClientProps {
  initialClients: Client[]
  tagLibrary: ClientTag[]
}

export function ClientsPageClient({ initialClients, tagLibrary }: ClientsPageClientProps) {
  const router = useRouter()
  const searchParams = useSearchParams()

  const [clients, setClients] = useState<Client[]>(initialClients)
  const [filters, setFilters] = useState<ClientFilters>(DEFAULT_FILTERS)
  const [selectedIds, setSelectedIds] = useState<string[]>([])
  const [loading, setLoading] = useState(false)
  const [fetchError, setFetchError] = useState<Error | null>(null)
  const [drawerOpen, setDrawerOpen] = useState(false)
  const [editingClient, setEditingClient] = useState<Client | null>(null)
  const [noteClientId, setNoteClientId] = useState<string | null>(null)
  const [page, setPage] = useState(1)
  const [hasMore, setHasMore] = useState(false)
  const [totalCount, setTotalCount] = useState<number | null>(null)

  // Saved views
  const [views, setViews] = useState<ClientView[]>([])
  const [activeViewId, setActiveViewId] = useState<string | null>(null)
  const [viewManagerOpen, setViewManagerOpen] = useState(false)
  const [viewManagerMode, setViewManagerMode] = useState<'create' | 'edit'>('create')
  const [editingView, setEditingView] = useState<ClientView | null>(null)
  const [hasUnsavedChanges, setHasUnsavedChanges] = useState(false)

  // Sort + column visibility
  const [sort, setSort] = useState<SortKey>(() => {
    if (typeof window !== 'undefined') {
      const sp = new URLSearchParams(window.location.search)
      const sortParam = sp.get('sort')
      if (sortParam) return sortParam as SortKey
    }
    return 'last_visit_desc'
  })
  const [visibleColumnKeys, setVisibleColumnKeys] = useState<string[]>(getInitialVisibleKeys)

  // Persist column visibility to localStorage
  useEffect(() => {
    try {
      window.localStorage.setItem(COLUMN_STORAGE_KEY, JSON.stringify(visibleColumnKeys))
    } catch {
      // Ignore storage errors
    }
  }, [visibleColumnKeys])

  // Persist sort to URL
  useEffect(() => {
    router.replace(
      sort !== 'last_visit_desc'
        ? `?sort=${sort}`
        : (searchParams.get('page') ? `?page=${searchParams.get('page')}` : ''),
      { scroll: false }
    )
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [sort])

  const fetchViews = useCallback(async () => {
    try {
      const res = await fetch('/api/client-views')
      if (res.ok) {
        const json = await res.json() as { data: ClientView[] }
        setViews(json.data ?? [])
        const defaultView = json.data?.find((v) => v.is_default)
        if (defaultView) {
          setActiveViewId((prev) => prev ?? defaultView.id)
        }
      }
    } catch {
      toast.error('Failed to load views', { description: 'Using All clients as default' })
    }
  }, [])

  useEffect(() => {
    void fetchViews()
  }, [fetchViews])

  // Restore page from URL
  useEffect(() => {
    const p = parseInt(searchParams.get('page') ?? '1', 10)
    if (p > 1) {
      setPage(p)
    }
  }, []) // eslint-disable-line react-hooks/exhaustive-deps

  const fetchClients = useCallback(async (f: ClientFilters, p = 1, sortKey: SortKey = 'last_visit_desc') => {
    setLoading(true)
    setFetchError(null)
    try {
      const params = new URLSearchParams()
      if (f.q) params.set('q', f.q)
      if (f.tags.length) params.set('tags', f.tags.join(','))
      if (f.vip) params.set('vip', 'true')
      if (f.inactive) params.set('inactive', 'true')
      if (f.noShows) params.set('no_show', 'true')
      if (!f.showArchived) params.set('archived', 'false')
      else params.set('archived', 'any')
      if (f.spendingTier) params.set('spending', f.spendingTier)
      if (f.artistIds.length) params.set('artist_ids', f.artistIds.join(','))
      if (f.serviceIds.length) params.set('service_ids', f.serviceIds.join(','))
      if (f.lastVisitRange) params.set('last_visit_range', f.lastVisitRange)
      if (f.hasAlerts) params.set('has_alerts', 'true')
      params.set('sort', sortKey)
      params.set('page', String(p))
      params.set('per_page', '50')

      const res = await fetch(`/api/clients?${params.toString()}`)
      if (!res.ok) throw new Error('Failed to load clients')
      const json = await res.json() as { data: Client[]; count: number }

      if (p === 1) {
        setClients(json.data ?? [])
      } else {
        setClients((prev) => [...prev, ...(json.data ?? [])])
      }
      setTotalCount(json.count ?? null)
      setHasMore((json.data?.length ?? 0) >= 50)
    } catch (err) {
      setFetchError(err instanceof Error ? err : new Error('Failed to load clients'))
    } finally {
      setLoading(false)
    }
  }, [])

  useEffect(() => {
    void fetchClients(filters, 1, sort)
    setPage(1)
    setSelectedIds([])
  }, [filters, sort, fetchClients])

  function handleFiltersChange(f: ClientFilters) {
    setFilters(f)
    setHasUnsavedChanges(true)
  }

  function handleViewChange(viewId: string | null) {
    setActiveViewId(viewId)
    setHasUnsavedChanges(false)
    const view = views.find((v) => v.id === viewId)
    if (view) {
      const viewFilters = view.filters as Partial<ClientFilters>
      setFilters({ ...DEFAULT_FILTERS, ...viewFilters })
    } else {
      setFilters(DEFAULT_FILTERS)
    }
  }

  async function handleDeleteView(viewId: string) {
    try {
      const res = await fetch(`/api/client-views/${viewId}`, { method: 'DELETE' })
      if (!res.ok) throw new Error('Failed to delete view')
      setViews((prev) => prev.filter((v) => v.id !== viewId))
      if (activeViewId === viewId) {
        const defaultView = views.find((v) => v.is_default)
        setActiveViewId(defaultView?.id ?? null)
      }
      toast.success('View deleted')
    } catch {
      toast.error('Failed to delete view')
    }
  }

  async function handleDuplicateView(view: ClientView) {
    try {
      const res = await fetch('/api/client-views', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: `${view.name} (copy)`,
          filters: view.filters,
          scope: 'private',
        }),
      })
      if (!res.ok) throw new Error('Failed to duplicate view')
      const json = await res.json() as { data: ClientView }
      setViews((prev) => [...prev, json.data])
      toast.success('View duplicated')
    } catch {
      toast.error('Failed to duplicate view')
    }
  }

  async function handleSetDefaultView(view: ClientView) {
    try {
      const res = await fetch(`/api/client-views/${view.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ is_default: true }),
      })
      if (!res.ok) throw new Error('Failed to set default')
      setViews((prev) => prev.map((v) => ({ ...v, is_default: v.id === view.id })))
      toast.success(`"${view.name}" is now your default view`)
    } catch {
      toast.error('Failed to set default view')
    }
  }

  function handleViewSaved(savedView: ClientView) {
    setViews((prev) => {
      const idx = prev.findIndex((v) => v.id === savedView.id)
      if (idx >= 0) {
        const next = [...prev]
        next[idx] = savedView
        return next
      }
      return [...prev, savedView]
    })
    setActiveViewId(savedView.id)
    setHasUnsavedChanges(false)
  }

  function handleLoadMore() {
    const nextPage = page + 1
    setPage(nextPage)
    router.replace(`?page=${nextPage}`, { scroll: false })
    void fetchClients(filters, nextPage, sort)
  }

  function handleEditClient(client: Client) {
    setEditingClient(client)
    setDrawerOpen(true)
  }

  function handleNewClient() {
    setEditingClient(null)
    setDrawerOpen(true)
  }

  function handleDrawerSuccess(client: Client) {
    setClients((prev) => {
      const idx = prev.findIndex((c) => c.id === client.id)
      if (idx >= 0) {
        const next = [...prev]
        next[idx] = client
        return next
      }
      return [client, ...prev]
    })
    void fetchClients(filters, 1, sort)
  }

  const hasActiveFilters = !!(
    filters.q || filters.tags.length > 0 || filters.vip ||
    filters.inactive || filters.noShows || filters.spendingTier ||
    filters.artistIds.length > 0 || filters.serviceIds.length > 0 || filters.lastVisitRange
  )

  const inactiveCount = useMemo(() => {
    const cutoff = Date.now() - 90 * 24 * 60 * 60 * 1000
    return clients.filter(
      (c) => !c.archived_at && c.last_visit_at !== null && new Date(c.last_visit_at).getTime() < cutoff
    ).length
  }, [clients])

  const isInitialLoad = loading && clients.length === 0

  // SavedViewSwitcher import kept — used by SavedViewManager internally
  void SavedViewSwitcher

  return (
    <PullToRefresh
      onRefresh={async () => { router.refresh() }}
      className="flex flex-col gap-6"
    >
      {/* ── Views row + primary action ─────────────────────────────────────── */}
      <div className="flex items-end justify-between gap-4 border-b border-border">
        <div className="flex-1 min-w-0 overflow-x-auto scrollbar-none [mask-image:linear-gradient(to_right,transparent_0px,black_16px,black_calc(100%-16px),transparent_100%)] md:[mask-image:none]">
          {views.length > 0 ? (
            <ClientsViewTabs
              views={views}
              activeViewId={activeViewId}
              hasUnsavedChanges={hasUnsavedChanges}
              onViewChange={handleViewChange}
              onCreateView={() => {
                setViewManagerMode('create')
                setEditingView(null)
                setViewManagerOpen(true)
              }}
              onEditView={(view) => {
                setViewManagerMode('edit')
                setEditingView(view)
                setViewManagerOpen(true)
              }}
              onDuplicateView={handleDuplicateView}
              onDeleteView={handleDeleteView}
              onSetDefault={handleSetDefaultView}
            />
          ) : (
            <div className="h-10" aria-hidden="true" />
          )}
        </div>
        <div className="flex shrink-0 items-center gap-2 pb-2">
          {inactiveCount > 0 && (
            <span
              title={`${inactiveCount} client${inactiveCount !== 1 ? 's' : ''} not seen in 90+ days`}
              className="inline-flex items-center gap-1 rounded-full bg-destructive/10 text-destructive text-[11px] font-medium px-2 py-0.5 select-none"
            >
              <span className="h-1.5 w-1.5 rounded-full bg-destructive shrink-0" aria-hidden="true" />
              {inactiveCount} inactive
            </span>
          )}
          <Button size="sm" onClick={handleNewClient}>
            <Plus className="mr-1.5 h-3.5 w-3.5" aria-hidden="true" />
            New client
          </Button>
        </div>
      </div>

      {/* ── Toolbar row (search + filters + sort + columns) ────────────────── */}
      <ClientsToolbar
        search={filters.q}
        onSearchChange={(q) => handleFiltersChange({ ...filters, q })}
        filters={filters}
        onFiltersChange={handleFiltersChange}
        sort={sort}
        onSortChange={setSort}
        columns={COLUMN_DEFS}
        visibleColumnKeys={visibleColumnKeys}
        onVisibleColumnsChange={setVisibleColumnKeys}
        tagLibrary={tagLibrary}
        showArchived={filters.showArchived}
        onToggleArchived={() => handleFiltersChange({ ...filters, showArchived: !filters.showArchived })}
      />

      {/* ── Bulk actions ───────────────────────────────────────────────────── */}
      {selectedIds.length > 0 && (
        <BulkActionsBar
          selectedIds={selectedIds}
          tagLibrary={tagLibrary}
          onClearSelection={() => setSelectedIds([])}
          onArchived={() => void fetchClients(filters, 1, sort)}
          onTagsApplied={() => void fetchClients(filters, 1, sort)}
        />
      )}

      {/* ── Table / empty / error ──────────────────────────────────────────── */}
      <DataState
        data={clients}
        isLoading={isInitialLoad}
        isError={!!fetchError && clients.length === 0}
        error={fetchError}
        loadingSlot={<TableSkeleton rows={8} />}
        emptySlot={
          hasActiveFilters || (activeViewId) ? (
            activeViewId ? (
              <EmptyState
                icon={BookmarkX}
                title="No clients match these filters"
                description={`The filters in "${views.find((v) => v.id === activeViewId)?.name ?? 'this view'}" returned no results.`}
                cta={{
                  label: 'Clear filters',
                  onClick: () => {
                    setFilters(DEFAULT_FILTERS)
                    setHasUnsavedChanges(false)
                  },
                }}
                ctaSecondary={{
                  label: 'Edit view filters',
                  onClick: () => {
                    const view = views.find((v) => v.id === activeViewId) ?? null
                    if (view) {
                      setViewManagerMode('edit')
                      setEditingView(view)
                      setViewManagerOpen(true)
                    }
                  },
                }}
                variant="no-results"
              />
            ) : (
              <EmptyState
                icon={SearchX}
                title="No clients match these filters"
                description="Try different filters or clear all to see everyone."
                cta={{
                  label: 'Clear filters',
                  onClick: () => {
                    setFilters(DEFAULT_FILTERS)
                    setHasUnsavedChanges(false)
                  },
                }}
                variant="no-results"
              />
            )
          ) : (
            <EmptyState
              icon={Users}
              title="Add your first client"
              description="Start with a manual entry — CSV import is coming soon."
              cta={{ label: '+ New client', onClick: handleNewClient }}
              ctaSecondary={{
                label: 'Import from CSV',
                onClick: () => toast.info('CSV import is coming soon. Add clients manually for now.'),
              }}
              variant="first-time"
            />
          )
        }
        errorSlot={
          <PageError
            error={fetchError ?? new Error('Failed to load clients')}
            reset={() => void fetchClients(filters, 1, sort)}
            variant="inline"
          />
        }
      >
        {(data) => (
          <ClientsTable
            clients={data}
            tagLibrary={tagLibrary}
            loading={loading && data.length === 0}
            selectedIds={selectedIds}
            onSelectionChange={setSelectedIds}
            onEdit={handleEditClient}
            onAddNote={(id) => setNoteClientId(id)}
          />
        )}
      </DataState>

      {/* ── Load more + count footer ───────────────────────────────────────── */}
      {(hasMore || loading) && clients.length > 0 && (
        <div className="flex items-center justify-between py-4">
          <span className="text-sm text-muted-foreground tabular-nums">
            Showing {clients.length}{totalCount !== null ? ` of ${totalCount}` : ''} clients
          </span>
          {hasMore && (
            <Button variant="outline" size="sm" onClick={handleLoadMore} disabled={loading}>
              {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" aria-hidden="true" />}
              Load more
            </Button>
          )}
        </div>
      )}
      {/* Count footer when no "load more" is shown */}
      {!hasMore && !loading && clients.length > 0 && totalCount !== null && (
        <p className="text-xs text-muted-foreground text-right tabular-nums">
          Showing {clients.length} of {totalCount}
        </p>
      )}

      <ClientDrawer
        open={drawerOpen}
        onOpenChange={(v) => {
          setDrawerOpen(v)
          if (!v) setEditingClient(null)
        }}
        client={editingClient}
        tagLibrary={tagLibrary}
        onSuccess={handleDrawerSuccess}
      />

      {noteClientId && (
        <AddNoteModal
          open={Boolean(noteClientId)}
          onOpenChange={(v) => { if (!v) setNoteClientId(null) }}
          clientId={noteClientId}
        />
      )}

      <SavedViewManager
        open={viewManagerOpen}
        onOpenChange={setViewManagerOpen}
        mode={viewManagerMode}
        view={editingView}
        currentFilters={filters}
        onSaved={handleViewSaved}
      />
    </PullToRefresh>
  )
}

